/**
 * IndexedDB storage for Ed25519 keypairs
 * SRS §3.2.2: Secure client-side key storage
 */

const DB_NAME = 'monoterminal-auth';
const DB_VERSION = 1;
const STORE_NAME = 'keypairs';

export interface StoredKeypair {
  publicKey: Uint8Array;
  privateKey: Uint8Array;
  createdAt: number;
  lastUsed: number;
}

/**
 * Initialize IndexedDB database
 */
function openDatabase(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onerror = () => {
      reject(new Error(`Failed to open database: ${request.error?.message}`));
    };

    request.onsuccess = () => {
      resolve(request.result);
    };

    request.onupgradeneeded = (event) => {
      const db = (event.target as IDBOpenDBRequest).result;

      // Create keypairs object store if it doesn't exist
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: 'id' });
      }
    };
  });
}

/**
 * Store Ed25519 keypair in IndexedDB
 */
export async function storeKeypair(
  id: string,
  publicKey: Uint8Array,
  privateKey: Uint8Array
): Promise<void> {
  const db = await openDatabase();

  return new Promise((resolve, reject) => {
    const transaction = db.transaction(STORE_NAME, 'readwrite');
    const store = transaction.objectStore(STORE_NAME);

    const keypair: StoredKeypair & { id: string } = {
      id,
      publicKey,
      privateKey,
      createdAt: Date.now(),
      lastUsed: Date.now(),
    };

    const request = store.put(keypair);

    request.onerror = () => {
      reject(new Error(`Failed to store keypair: ${request.error?.message}`));
    };

    request.onsuccess = () => {
      resolve();
    };

    transaction.oncomplete = () => {
      db.close();
    };
  });
}

/**
 * Load Ed25519 keypair from IndexedDB
 */
export async function loadKeypair(id: string): Promise<StoredKeypair | null> {
  const db = await openDatabase();

  return new Promise((resolve, reject) => {
    const transaction = db.transaction(STORE_NAME, 'readwrite');
    const store = transaction.objectStore(STORE_NAME);

    const request = store.get(id);

    request.onerror = () => {
      reject(new Error(`Failed to load keypair: ${request.error?.message}`));
    };

    request.onsuccess = () => {
      const result = request.result as (StoredKeypair & { id: string }) | undefined;

      if (result) {
        // Update lastUsed timestamp
        result.lastUsed = Date.now();
        store.put(result);
        resolve(result);
      } else {
        resolve(null);
      }
    };

    transaction.oncomplete = () => {
      db.close();
    };
  });
}

/**
 * Delete keypair from IndexedDB
 */
export async function deleteKeypair(id: string): Promise<void> {
  const db = await openDatabase();

  return new Promise((resolve, reject) => {
    const transaction = db.transaction(STORE_NAME, 'readwrite');
    const store = transaction.objectStore(STORE_NAME);

    const request = store.delete(id);

    request.onerror = () => {
      reject(new Error(`Failed to delete keypair: ${request.error?.message}`));
    };

    request.onsuccess = () => {
      resolve();
    };

    transaction.oncomplete = () => {
      db.close();
    };
  });
}

/**
 * List all stored keypairs (metadata only, no private keys)
 */
export async function listKeypairs(): Promise<Array<{ id: string; publicKey: Uint8Array; createdAt: number; lastUsed: number }>> {
  const db = await openDatabase();

  return new Promise((resolve, reject) => {
    const transaction = db.transaction(STORE_NAME, 'readonly');
    const store = transaction.objectStore(STORE_NAME);

    const request = store.getAll();

    request.onerror = () => {
      reject(new Error(`Failed to list keypairs: ${request.error?.message}`));
    };

    request.onsuccess = () => {
      const results = (request.result || []).map((kp: StoredKeypair & { id: string }) => ({
        id: kp.id,
        publicKey: kp.publicKey,
        createdAt: kp.createdAt,
        lastUsed: kp.lastUsed,
      }));
      resolve(results);
    };

    transaction.oncomplete = () => {
      db.close();
    };
  });
}

/**
 * Ed25519 key generation and management for browser
 * SRS §3.2.2: Client-side Ed25519 authentication
 *
 * Uses @noble/ed25519 for broad browser compatibility
 * (WebCrypto API doesn't support Ed25519 in all target browsers)
 */

import * as ed25519 from '@noble/ed25519';
import { storeKeypair, loadKeypair } from './storage';

export interface Ed25519Keypair {
  publicKey: Uint8Array;  // 32 bytes
  privateKey: Uint8Array; // 32 bytes
}

/**
 * Generate a new Ed25519 keypair using cryptographically secure random
 */
export async function generateKeypair(): Promise<Ed25519Keypair> {
  // Generate random 32-byte private key
  const privateKey = ed25519.utils.randomPrivateKey();

  // Derive public key from private key
  const publicKey = await ed25519.getPublicKeyAsync(privateKey);

  return {
    publicKey,
    privateKey,
  };
}

/**
 * Sign a message/challenge with Ed25519 private key
 *
 * @param message - The message to sign (typically a 32-byte challenge nonce)
 * @param privateKey - The Ed25519 private key (32 bytes)
 * @returns Ed25519 signature (64 bytes)
 */
export async function sign(message: Uint8Array, privateKey: Uint8Array): Promise<Uint8Array> {
  return await ed25519.signAsync(message, privateKey);
}

/**
 * Verify an Ed25519 signature (for testing purposes)
 *
 * @param signature - The signature to verify (64 bytes)
 * @param message - The original message
 * @param publicKey - The public key (32 bytes)
 * @returns true if signature is valid
 */
export async function verify(
  signature: Uint8Array,
  message: Uint8Array,
  publicKey: Uint8Array
): Promise<boolean> {
  return await ed25519.verifyAsync(signature, message, publicKey);
}

/**
 * Load or generate Ed25519 keypair for the default identity
 *
 * This is the main entry point for getting a keypair:
 * - Loads from IndexedDB if exists
 * - Generates new keypair if not found
 * - Stores the new keypair in IndexedDB
 *
 * @param id - Keypair identifier (default: 'default')
 * @returns Ed25519 keypair
 */
export async function loadOrGenerateKeypair(id: string = 'default'): Promise<Ed25519Keypair> {
  // Try to load existing keypair
  const stored = await loadKeypair(id);

  if (stored) {
    console.log(`Loaded existing Ed25519 keypair (id: ${id})`);
    return {
      publicKey: stored.publicKey,
      privateKey: stored.privateKey,
    };
  }

  // Generate new keypair
  console.log(`Generating new Ed25519 keypair (id: ${id})`);
  const keypair = await generateKeypair();

  // Store for future use
  await storeKeypair(id, keypair.publicKey, keypair.privateKey);

  return keypair;
}

/**
 * Get the public key fingerprint (hex-encoded)
 * Used for displaying the key identity to users
 *
 * @param publicKey - The Ed25519 public key (32 bytes)
 * @returns Hex-encoded fingerprint string
 */
export function getPublicKeyFingerprint(publicKey: Uint8Array): string {
  // Convert to hex string
  return Array.from(publicKey)
    .map(b => b.toString(16).padStart(2, '0'))
    .join('');
}

/**
 * Format public key as base64 (for transmission)
 */
export function publicKeyToBase64(publicKey: Uint8Array): string {
  return btoa(String.fromCharCode(...publicKey));
}

/**
 * Parse base64 public key
 */
export function publicKeyFromBase64(base64: string): Uint8Array {
  const binary = atob(base64);
  return Uint8Array.from(binary, c => c.charCodeAt(0));
}

/**
 * Challenge-response authentication client
 * SRS §3.2.2: Ed25519 challenge-response flow
 *
 * Flow:
 * 1. Request challenge from server
 * 2. Server sends 32-byte random nonce
 * 3. Client signs nonce with Ed25519 private key
 * 4. Client sends signature + public key to server
 * 5. Server verifies signature and issues JWT
 */

import { sign } from './keys';

export interface Challenge {
  nonce: Uint8Array;       // 32-byte random challenge
  expiresAt: number;       // Unix timestamp (ms)
}

export interface ChallengeResponse {
  signature: Uint8Array;   // 64-byte Ed25519 signature
  publicKey: Uint8Array;   // 32-byte Ed25519 public key
}

/**
 * Parse challenge from server
 * Expects JSON: { nonce: string (base64), expiresAt: number }
 */
export function parseChallenge(data: any): Challenge {
  if (!data.nonce || typeof data.expiresAt !== 'number') {
    throw new Error('Invalid challenge format');
  }

  // Decode base64 nonce
  const nonce = Uint8Array.from(atob(data.nonce), c => c.charCodeAt(0));

  if (nonce.length !== 32) {
    throw new Error(`Invalid nonce length: expected 32 bytes, got ${nonce.length}`);
  }

  return {
    nonce,
    expiresAt: data.expiresAt,
  };
}

/**
 * Check if challenge has expired
 */
export function isChallengeExpired(challenge: Challenge): boolean {
  return Date.now() > challenge.expiresAt;
}

/**
 * Sign a challenge with Ed25519 private key
 *
 * @param challenge - The challenge received from server
 * @param privateKey - The Ed25519 private key (32 bytes)
 * @param publicKey - The Ed25519 public key (32 bytes)
 * @returns Challenge response with signature and public key
 */
export async function signChallenge(
  challenge: Challenge,
  privateKey: Uint8Array,
  publicKey: Uint8Array
): Promise<ChallengeResponse> {
  // Check expiration
  if (isChallengeExpired(challenge)) {
    throw new Error('Challenge has expired');
  }

  // Sign the challenge nonce
  const signature = await sign(challenge.nonce, privateKey);

  if (signature.length !== 64) {
    throw new Error(`Invalid signature length: expected 64 bytes, got ${signature.length}`);
  }

  return {
    signature,
    publicKey,
  };
}

/**
 * Serialize challenge response for transmission
 * Returns JSON-serializable object with base64-encoded binary data
 */
export function serializeChallengeResponse(response: ChallengeResponse): {
  signature: string;
  publicKey: string;
} {
  return {
    signature: btoa(String.fromCharCode(...response.signature)),
    publicKey: btoa(String.fromCharCode(...response.publicKey)),
  };
}

/**
 * Browser Ed25519 Authentication Service
 * SRS §3.2.2: Client-side authentication implementation
 *
 * Main entry point for authentication operations:
 * - Keypair generation and storage
 * - Challenge-response signing
 * - JWT token management
 */

import {
  loadOrGenerateKeypair,
  generateKeypair,
  getPublicKeyFingerprint,
  publicKeyToBase64,
  type Ed25519Keypair,
} from './keys';
import {
  signChallenge,
  serializeChallengeResponse,
  parseChallenge,
  isChallengeExpired,
  type Challenge,
  type ChallengeResponse,
} from './challenge';
import { deleteKeypair } from './storage';

// Re-export types and utilities
export type { Ed25519Keypair, Challenge, ChallengeResponse };
export {
  generateKeypair,
  getPublicKeyFingerprint,
  publicKeyToBase64,
  parseChallenge,
  isChallengeExpired,
};

/**
 * Authentication service for Ed25519 challenge-response flow
 */
export class AuthService {
  private keypair: Ed25519Keypair | null = null;
  private jwt: string | null = null;
  private jwtExpiresAt: number | null = null;

  /**
   * Initialize auth service and load/generate keypair
   */
  async initialize(keypairId: string = 'default'): Promise<void> {
    this.keypair = await loadOrGenerateKeypair(keypairId);
    console.log('Auth service initialized');
  }

  /**
   * Get the public key (for display/transmission)
   */
  getPublicKey(): Uint8Array {
    if (!this.keypair) {
      throw new Error('Auth service not initialized. Call initialize() first.');
    }
    return this.keypair.publicKey;
  }

  /**
   * Get the public key fingerprint (hex string)
   */
  getPublicKeyFingerprint(): string {
    return getPublicKeyFingerprint(this.getPublicKey());
  }

  /**
   * Get the public key as base64 (for transmission)
   */
  getPublicKeyBase64(): string {
    return publicKeyToBase64(this.getPublicKey());
  }

  /**
   * Sign a challenge received from the server
   *
   * @param challengeData - Challenge data from server (JSON)
   * @returns Serialized challenge response (signature + public key as base64)
   */
  async signChallenge(challengeData: any): Promise<{ signature: string; publicKey: string }> {
    if (!this.keypair) {
      throw new Error('Auth service not initialized. Call initialize() first.');
    }

    const challenge = parseChallenge(challengeData);
    const response = await signChallenge(challenge, this.keypair.privateKey, this.keypair.publicKey);
    return serializeChallengeResponse(response);
  }

  /**
   * Store JWT token received after successful authentication
   *
   * @param token - JWT access token
   * @param expiresIn - Token lifetime in seconds (default: 900 = 15 minutes per SRS)
   */
  setJWT(token: string, expiresIn: number = 900): void {
    this.jwt = token;
    this.jwtExpiresAt = Date.now() + expiresIn * 1000;
    console.log(`JWT stored, expires at ${new Date(this.jwtExpiresAt).toISOString()}`);
  }

  /**
   * Get current JWT token
   *
   * @returns JWT token or null if not authenticated
   */
  getJWT(): string | null {
    // Check expiration
    if (this.jwt && this.jwtExpiresAt && Date.now() > this.jwtExpiresAt) {
      console.warn('JWT expired');
      this.jwt = null;
      this.jwtExpiresAt = null;
      return null;
    }

    return this.jwt;
  }

  /**
   * Check if currently authenticated (has valid JWT)
   */
  isAuthenticated(): boolean {
    return this.getJWT() !== null;
  }

  /**
   * Clear JWT token (logout)
   */
  clearJWT(): void {
    this.jwt = null;
    this.jwtExpiresAt = null;
    console.log('JWT cleared');
  }

  /**
   * Get time until JWT expiration (in seconds)
   */
  getJWTTimeRemaining(): number | null {
    if (!this.jwtExpiresAt) {
      return null;
    }

    const remaining = Math.max(0, (this.jwtExpiresAt - Date.now()) / 1000);
    return remaining > 0 ? remaining : null;
  }

  /**
   * Reset authentication (clear JWT and delete keypair)
   * Use with caution - this will require generating a new keypair
   */
  async reset(keypairId: string = 'default'): Promise<void> {
    this.clearJWT();
    await deleteKeypair(keypairId);
    this.keypair = null;
    console.log('Auth service reset - keypair deleted');
  }
}

/**
 * Create and initialize a new auth service instance
 * Convenience function for common use case
 */
export async function createAuthService(keypairId: string = 'default'): Promise<AuthService> {
  const service = new AuthService();
  await service.initialize(keypairId);
  return service;
}

